SELECT r.job_id, r.artifact_ref, r.owner_id, r.format, r.scope, r.status, r.report_spec_json, r.report_fill_json, r.report_print_json, r.metadata_json, r.diagnostics_json, r.submitted_at, r.retention_ttl_sec, r.report_run_revision, r.conversation_id, r.workspace_id, r.auth_context_ref, r.artifact_id, r.error_text, r.started_at, r.completed_at, r.report_run_id, r.export_request_id FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM report_export_job c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)